const rating = context.item.data?.['ratingvalue'];

if (rating < 5) {
    return '#FF4444';
} else if (rating >= 5 && rating < 7) {
    return 'gray';
} else if (rating >= 7 && rating < 10) {
    return 'green';
} else if (rating === 10) {
    return 'linear-gradient(135deg, #FDCA00 0%, #A46B00 100%)';
}

const image = context.item.data?.['image'];

// Если пусто (null, undefined, пустая строка или только пробелы) → true
// Если есть значение → false
return !image || (typeof image === 'string' && image.trim() === '');

// Проверяем, что context.item и context.item.data реально есть
if (!context.item || !context.item.data) return '';

// Берём цвета и угол
const color1 = context.item.data?.['gradient_color_1'];
const color2 = context.item.data?.['gradient_color_2'];
const angle = context.item.data?.['gradient_angle'] ?? 45; // если нет угла, ставим 45°

if (!color1 || !color2) {
    // fallback, если нет цветов
    return 'linear-gradient(45deg, #232526, #414345)';
}

// Приводим к строке и убираем лишние кавычки/пробелы
const safeColor1 = String(color1).replace(/['"]/g, '').trim();
const safeColor2 = String(color2).replace(/['"]/g, '').trim();
const safeAngle = Number(angle); // на всякий случай

// Возвращаем готовый CSS
return 'linear-gradient(' + safeAngle + 'deg, ' + safeColor1 + ', ' + safeColor2 + ')';

const image = context.item.data?.['game_image'];

// Если пусто (null, undefined, пустая строка или только пробелы) → true
// Если есть значение → false
return !image || (typeof image === 'string' && image.trim() === '');

