const data = collections['09a81a55-f69c-49b7-a805-5e0fe623f06d']?.data || [];

const lang = globalContext.page?.['lang'] || 'ru';
const textColor = globalContext.browser?.theme === "light" ? "#000000" : "#FFFFFF";

let total = 0;
const counts = {};
for (let i = 1; i <= 10; i++) counts[i] = 0;

data.forEach(item => {
    const value = item?.ratingvalue;
    if (value >= 1 && value <= 10) {
        counts[value]++;
        total++;
    }
});

const colors = [
    '#8B0000', '#B22222', '#DC143C', '#FF4500',
    '#404040', '#808080',
    '#006400', '#228B22', '#32CD32',
    '#FDCA00'
];

// Создаем labels для легенды
const legendLabels = Object.entries(counts).map(([rating, count]) => {
    const percentage = total > 0 ? ((count / total) * 100).toFixed(1) : 0;
    return `${rating} - ${percentage}%`;
});

return {
    responsive: true,
    maintainAspectRatio: true,
    aspectRatio: 2,
    cutout: '50%',
    plugins: {
        legend: {
            display: true,
            position: 'right',
            labels: {
                color: textColor,
                font: { size: 12 },
                usePointStyle: true,
                pointStyle: 'circle',
                generateLabels: () => {
                    return legendLabels.map((label, i) => {
                        const [rating] = label.split(' - ');
                        return {
                            text: label,
                            fillStyle: colors[i],
                            strokeStyle: colors[i],
                            lineWidth: 2,
                            hidden: false,
                            index: i,
                            pointStyle: 'circle'
                        };
                    });
                }
            }
        },
        tooltip: {
            backgroundColor: 'rgba(0, 0, 0, 0.9)',
            titleColor: '#FDCA00',
            bodyColor: '#fff',
            borderColor: '#FDCA00',
            borderWidth: 2,
            borderRadius: 8,
            titleFont: { size: 14, weight: 'bold' },
            bodyFont: { size: 13 },
            padding: 12,
            displayColors: true,
            usePointStyle: true,
            callbacks: {
                title: (context) => {
                    const label = legendLabels[context[0].dataIndex];
                    const [rating] = label.split(' - ');
                    return lang === 'ru' ? `Оценка ${rating}` : `Rating ${rating}`;
                },
                label: (context) => {
                    const count = context.raw;
                    const percentage = ((count / total) * 100).toFixed(1);
                    const countText = lang === 'ru' ? 'оценок' : 'ratings';
                    return ` ${count} ${countText} (${percentage}%)`;
                }
            }
        }
    }
};

