        value: ratingvalue,
        percentage: total > 0 ? Math.round((count / total) * 100) : 0,
        percentage_decimal: total > 0 ? (count / total * 100).toFixed(1) : "0.0"
    }))
    .sort((a, b) => Number(a.value) - Number(b.value));

console.log('Всего оценок:', total);
console.log('Результат:', result);

return result;

