const data = collections['e80658fd-b4d3-4dd7-a6cf-d2f7fb3728f9']?.data || [];

const lang = globalContext.page?.['lang'] || 'ru';
const textColor = globalContext.browser?.theme === "light" ? "#000000" : "#FFFFFF";

// Собираем все теги из записей
const allTags = [];
data.forEach(item => {
    const tags = item?.tags;
    if (Array.isArray(tags)) {
        allTags.push(...tags);
    } else if (typeof tags === 'string') {
        allTags.push(tags);
    }
});

// Считаем частоту каждого тега
const tagCounts = {};
allTags.forEach(tag => {
    if (tag && tag.trim()) {
        tagCounts[tag] = (tagCounts[tag] || 0) + 1;
    }
});

// Общее количество упоминаний тегов
const total = allTags.length;

// Берем топ-5 тегов
const topTags = Object.entries(tagCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5);

const colors = ['#FF6384', '#36A2EB', '#FFCE56', '#4BC0C0', '#9966FF'];

return {
    responsive: true,
    maintainAspectRatio: true,
    aspectRatio: 2,
    cutout: '50%',
    plugins: {
        legend: {
            display: true,
            position: 'right',
            labels: {
                color: textColor,
                font: { size: 12 },
                usePointStyle: true,
                pointStyle: 'circle',
                generateLabels: () => {
                    return topTags.map(([tag, count], i) => ({
                        text: `${tag} - ${((count / total) * 100).toFixed(1)}%`,
                        fillStyle: colors[i],
                        strokeStyle: colors[i],
                        lineWidth: 2,
                        hidden: false,
                        index: i,
                        pointStyle: 'circle'
                    }));
                }
            }
        },
        tooltip: {
            backgroundColor: 'rgba(0, 0, 0, 0.9)',
            titleColor: '#FDCA00',
            bodyColor: '#fff',
            borderColor: '#FDCA00',
            borderWidth: 2,
            borderRadius: 8,
            titleFont: { size: 14, weight: 'bold' },
            bodyFont: { size: 13 },
            padding: 12,
            displayColors: true,
            usePointStyle: true,
            callbacks: {
                title: (context) => {
                    return topTags[context[0].dataIndex]?.[0] || (lang === 'ru' ? 'Тег' : 'Tag');
                },
                label: (context) => {
                    const count = context.raw;
                    const percentage = ((count / total) * 100).toFixed(1);

                    if (lang === 'ru') {
                        const gameWord = count === 1 ? 'игра' : 'игр';
                        return ` ${count} ${gameWord} (${percentage}%)`;
                    } else {
                        const gameWord = count === 1 ? 'game' : 'games';
                        return ` ${count} ${gameWord} (${percentage}%)`;
                    }
                }
            }
        }
    }
};

