return {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
        legend: { display: false },
        tooltip: {
            backgroundColor: 'rgba(0, 0, 0, 0.8)',
            titleColor: '#FDCA00',
            bodyColor: '#fff',
            borderColor: '#FDCA00',
            borderWidth: 1,
            displayColors: false,
            callbacks: {
                title: (context) => {
                    const item = filteredData[context[0].dataIndex];
                    return item?.game_title || (lang === 'ru' ? 'Неизвестная игра' : 'Unknown game');
                },
                label: (context) => {
                    const ratingText = lang === 'ru' ? 'Оценка' : 'Rating';
                    return `${ratingText}: ${context.raw}/10`;
                },
                afterLabel: (context) => {
                    const item = filteredData[context.dataIndex];
                    const date = new Date(item.inserted_at);

                    if (lang === 'ru') {
                        return `${date.getDate().toString().padStart(2, '0')}.${(date.getMonth() + 1).toString().padStart(2, '0')}.${date.getFullYear()}`;
                    } else {
                        // Английский формат: месяц/день/год или день месяц год
                        const month = date.toLocaleString('en-US', { month: 'short' });
                        return `${month} ${date.getDate()}, ${date.getFullYear()}`; // "Mar 12, 2026"
                    }
                }
            }
        }
    },
    scales: {
        y: {
            beginAtZero: false,
            min: 1,
            max: 10,
            grid: { color: 'rgba(0, 0, 0, 0.1)' },
            title: { display: false },
            ticks: {
                display: true,
                stepSize: 1
            }
        },
        x: {
            grid: { display: false },
            title: { display: false },
            ticks: { display: false }
        }
    }
};

